<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import {Reading,ArrowRight,InfoFilled} from '@element-plus/icons-vue'
defineProps<{embedded?:boolean}>()
const route=useRoute(),open=ref(false),selected=ref(''),complete=ref(false),reading=ref<HTMLElement|null>(null)
const guides=[
 {key:'overview',title:'系统功能简介',intro:'从客户采购信息到内部销售订单，保留每一步处理依据。',steps:[['准备客户配置','选择客户，维护 Excel 字段映射和历史匹配规则。标准 Excel 与智能解析使用各自入口。'],['核对导入结果','每份文件有独立任务，每条采购显示处理结果。有可靠历史参考且检查通过时可自动建单。'],['处理并查看订单','在任务详情修正问题、核实重复采购，或人工补全产品与价格。销售订单可查看来源、状态和操作记录。']],tip:'本系统包含模拟 SEED 历史，它们用于演示，不代表真实 OMS 数据；PDF 是内部详情报告。'},
 {key:'customers',title:'客户配置与字段映射',intro:'每个客户使用一套正式配置，保存后仅新导入任务使用新版本。',steps:[['选择客户与模板','新增或维护客户，上传 .xlsx 样例。核对工作表及表头行；位置改变后重新识别。'],['逐列选择含义','完整表头按原始位置展示。只映射需要的列，其他列保持未映射，以后仍可追加；字段也可以取消或改选。重复或空表头保留位置，需要映射时先整理原模板。'],['预览并保存','编辑时可预览映射关系；上传样例后可预览实际数据和必填字段问题。核对匹配规则，确认保存新版本。']],tip:'A/B/C 是可修改的预设，至少选择一个合法匹配字段，统一产品及安全校验仍生效。A：采购单号＋料号；B：采购单号＋真正机型；C：料号＋批次且历史数量 > 500。不要补造 Excel 中没有的字段。旧配置若无法恢复完整表头，需要重新上传原模板。'},
 {key:'import',title:'标准与批量 Excel 导入',intro:'标准 Excel 直接使用已保存的字段映射，不调用 AI。',steps:[['选择文件并指定客户','支持一次选择多份 .xlsx，每份必须手动指定客户；同一客户可统一指定。系统不根据文件名猜客户。'],['检查重复提示','若提示相同文件，可查看上次结果、取消，或明确再次导入。再次独立导入发现已处理采购时需逐行核实，不能仅凭相同文件直接认定重复。'],['查看本次结果','上传后点击查看结果。各文件独立处理，正常行可继续建单，问题行在任务内处理。']],example:'同一次上传的第二份文件解析失败，不影响第一份文件的正常采购行。'},
 {key:'tasks',title:'任务查询与失败重传',intro:'任务列表是查找采购处理结果的统一入口，无需手动输入编号。',steps:[['筛选历史任务','按客户、文件名、日期与状态筛选，点击查看详情。任务编号用于联系同事、定位与追溯。'],['查看每行结果','详情中查看采购字段、Excel 原始行号、未处理原因和对应订单；配置版本与重传关联保留在任务信息中。'],['区分两种情况','文件解析失败时没有采购行，需要修复文件后从原任务重传；采购行 NOT_MATCHED 表示解析完成但没有可靠历史参考。']],tip:'部分成功不需要重新上传整份文件，先在原任务核查未处理行，避免重复提交。'},
 {key:'rows',title:'采购行处理与异常修正',intro:'在导入任务详情中处理采购行，按当前结果选择下一步。',steps:[['已建单：查看销售订单','通过行内订单入口查看金额、来源和状态。已处理采购行不能再次建单或修改。'],['未匹配：检查原信息','可查看未匹配原因及匹配规则。信息有误时选择修正信息，说明依据后重新校验；只修改本次采购，不改历史销售订单。'],['无可靠参考：人工补全','核实我司产品和合法单价后，使用人工补全新建。待核实重复采购时，应先完成重复核实；后台会继续检查。']],tip:'详情抽屉每次只展开一个处理表单，原始内容、来源订单和修正记录仍可查看。'},
 {key:'duplicate',title:'采购重复核实与连续翻单',intro:'技术重试与真实再次采购不同，相同物料、批次或数量本身不能判断是否重复。',steps:[['发现疑似重复时先核对','查看相符的已处理订单，并与客户需求确认记录比对。首次 C 采购不会仅因缺少采购单号被拦截；后续相似采购仍需核实。'],['选择实际结论','“这笔采购已经处理过”会关联已有订单，不再创建；“这是新的采购／加购”必须说明真实核实依据；稳定采购明细编号可选，若填写则同客户同编号只能建单一次。'],['确认历史参考资格','同客户、合格状态、唯一产品与正数历史单价全部满足后才可翻单。历史同产品候选按创建时间及 ID 倒序选价。确认订单不会立即生成下一单，仍需新采购导入。']],tip:'同一任务行不能重复建单。相同文件可代表独立新采购，但新任务发现已处理采购时必须先核实。原订单作废不代表新任务可自动重建，仍需核实真实需求；原任务没有作废重开入口。'},
 {key:'ai',title:'AI解析、修正与确认',intro:'AI 只提取采购信息，必须在人工确认后才进入订单处理流程。',steps:[['选择客户并提供内容','上传非标准 Excel、PDF、图片，或粘贴采购文字。实际调用 MiMo 前，确认内容已获授权，不含未经许可外传的客户机密。'],['逐行核对与修改','对照原文核对料号、机型、批次和数量，按当前草稿配置补齐必填项。多个产品分别显示；不确定字段不能猜。可先保存不完整草稿。'],['明确确认导入','完成修改保存并确认核对后点击确认导入。错误会显示在对应字段附近，修改后再提交。解析预览和保存草稿不会建单。']],example:'“X100 再订 200 台，X200 再订 300 台”应核对为两条采购，不能合并数量。',tip:'Mock 演示表示未调用 MiMo。真实调用会将本次输入发送至外部模型服务；AI 不会替你确认我司产品或销售价格。'},
 {key:'orders',title:'订单编辑、状态、作废与导出',intro:'从销售订单列表查看业务结果，来源与审计记录在订单详情保留。',steps:[['编辑与状态变更','业务订单仅在已创建状态可编辑，金额由后端计算。按已创建→已确认→进行中→已发货→已完成流转，确认后不可编辑。'],['作废需要原因与确认','仅符合条件的已创建业务订单可作废，需要填写原因并二次确认。作废不可恢复、编辑或继续流转，也不能成为历史参考。'],['按需查看和导出','默认隐藏已作废，可通过筛选查看。Excel 导出当前已查询条件的全部订单，最多 10000 条；详情可导出适合 A4 的中文 PDF 内部报告。']],tip:'保留的原采购、历史参考及来源占用不会因作废消失。详情会说明不能编辑或作废的原因。'},
 {key:'faq',title:'常见问题与处理办法',intro:'先核查当前结果和环境，再决定下一步，避免重复操作。',steps:[['找不到刚才的结果？','先看右上角演示环境 / 测试环境及连接状态，再到历史任务列表查询。这两个环境的数据相互隔离。'],['网络超时或版本冲突？','超时后先查看是否已完成，使用原操作重试；版本冲突时重新打开并核对最新信息，不要反复新建任务。'],['匹配失败或 AI 不可用？','历史匹配失败时核对客户规则和采购信息；没有可靠参考时人工核实产品与价格。AI 服务失败不影响标准 Excel 导入。']],tip:'保留任务编号、原始文件和明确错误原因方便排查。本帮助为本地静态手册，不调用 AI。'},
]
const current=computed(()=>route.path.startsWith('/order-entry')?(route.query.mode==='ai'?'ai':'import'):guides.find(g=>route.path.startsWith('/'+g.key))?.key||'overview')
watch(current,async value=>{selected.value=value;await nextTick();if(complete.value)scrollTo(value);else reading.value?.scrollTo?.({top:0})},{immediate:true})
const shown=computed(()=>complete.value?guides:guides.filter(g=>g.key===selected.value))
function scrollTo(key:string){const target=reading.value?.querySelector<HTMLElement>('#guide-'+key);if(target&&reading.value)reading.value.scrollTo?.({top:target.offsetTop-16,behavior:'smooth'})}
async function choose(key:string){selected.value=key;await nextTick();if(complete.value)scrollTo(key);else reading.value?.scrollTo?.({top:0})}
function show(){selected.value=current.value;complete.value=false;open.value=true}
async function manual(){complete.value=true;await nextTick();scrollTo(selected.value)}
</script>
<template>
<el-button v-if="!embedded" class="guide-button" circle type="primary" aria-label="打开操作指南" @click="show">?</el-button>
<component :is="embedded?'section':'el-drawer'" v-model="open" title="操作指南" size="min(980px,96vw)" class="operation-guide" :destroy-on-close="true">
<template #header><div class="guide-heading"><el-icon><Reading/></el-icon><div><h2>操作指南</h2><p>按业务步骤查找，遇到问题随时查看</p></div></div></template>
<div class="guide-layout"><nav class="guide-directory" aria-label="手册章节目录"><p class="directory-title">手册目录</p><button v-for="(g,i) in guides" :key="g.key" :class="{active:selected===g.key}" :aria-current="selected===g.key?'page':undefined" @click="choose(g.key)"><span>{{String(i+1).padStart(2,'0')}}</span>{{g.title}}<el-icon v-if="current===g.key" title="当前页面相关"><ArrowRight/></el-icon></button><div class="directory-note">当前页面相关章节已优先打开。关闭帮助不会清空正在填写的内容。</div></nav>
<div class="guide-main"><div class="guide-toolbar"><span>{{complete?'完整操作手册':'当前章节'}} · {{guides.length}} 个主题</span><el-button v-if="!complete" link type="primary" @click="manual">查看完整手册</el-button><el-button v-else link type="primary" @click="complete=false">只看选中章节</el-button></div>
<div ref="reading" class="guide-reading" tabindex="0" aria-label="操作说明"><article v-for="g in shown" :id="'guide-'+g.key" :key="g.key" class="guide-chapter"><div class="chapter-kicker">OrderFlow · 销管操作手册 <span v-if="g.key===current">当前页面相关</span></div><h2>{{g.title}}</h2><p class="chapter-intro">{{g.intro}}</p><ol class="guide-steps"><li v-for="(step,i) in g.steps" :key="step[0]"><span class="step-number">{{i+1}}</span><div><h3>{{step[0]}}</h3><p>{{step[1]}}</p></div></li></ol><div v-if="g.example" class="guide-example"><strong>操作示例</strong><p>{{g.example}}</p></div><aside v-if="g.tip" class="guide-tip"><el-icon><InfoFilled/></el-icon><p>{{g.tip}}</p></aside></article><p class="guide-footnote">以当前页面与服务器校验结果为准 · 版本记录与任务来源始终保留</p></div>
</div></div>
</component>
</template>
<style scoped>
