:1.5;color:#263c58;margin:12px 0}.chapter-intro{font-size:14px;color:#728297;line-height:1.8;margin:0 0 26px}.guide-steps{list-style:none;padding:0;margin:0}.guide-steps li{display:flex;gap:14px;margin:0 0 24px}.step-number{display:flex;align-items:center;justify-content:center;flex-shrink:0;width:28px;height:28px;border-radius:8px;color:#3e71ba;background:#eef4fd;font-size:13px;font-weight:600}.guide-steps h3{font-size:15px;color:#324a66;margin:2px 0 7px}.guide-steps p,.guide-example p,.guide-tip p{margin:0;color:#627389;font-size:14px;line-height:1.9;overflow-wrap:anywhere}.guide-example{background:#f6f8fb;border:1px solid #e9eff6;border-radius:10px;padding:16px 18px;margin:12px 0}.guide-example strong{display:block;font-size:12px;color:#6b7c93;margin-bottom:6px}.guide-tip{display:flex;gap:10px;border-left:3px solid #8fb3e8;background:#f3f7fd;padding:14px;border-radius:0 8px 8px 0;margin-top:16px}.guide-tip>.el-icon{color:#6a92cb;margin-top:5px;flex-shrink:0}.guide-tip p{font-size:13px}.guide-footnote{font-size:12px;line-height:1.8;color:#9aa7b7;text-align:center;margin:10px 0}
@media(max-width:760px){.guide-layout{grid-template-columns:1fr;grid-template-rows:auto minmax(0,1fr)}.guide-directory{display:flex;gap:6px;padding:10px;overflow-x:auto}.guide-directory button{width:auto;white-space:nowrap;padding:9px 12px}.directory-title,.directory-note,.guide-directory button span{display:none}.guide-reading{padding:20px}.guide-toolbar{padding:12px 20px}.guide-chapter h2{font-size:21px}.guide-button{right:12px;bottom:12px;width:36px;height:36px}}
</style>
